- CAP-PROCESS-MODEL: {"authority":"spawn exact admitted model profiles","id":"CAP-PROCESS-MODEL","status":"planned"}
- CAP-EVIDENCE-APPEND: {"authority":"append validated capsule types to a lineage","id":"CAP-EVIDENCE-APPEND","status":"planned"}
- CAP-GENERATION-PUBLISH: {"authority":"publish a verified immutable root","id":"CAP-GENERATION-PUBLISH","status":"planned"}
- CAP-ARCHIVE-READ: {"authority":"retrieve named immutable objects","id":"CAP-ARCHIVE-READ","status":"planned"}
- CAP-ARCHIVE-WRITE: {"authority":"create named immutable remote objects","id":"CAP-ARCHIVE-WRITE","status":"planned"}
- CAP-ARCHIVE-DELETE: {"authority":"apply an independently sealed deletion plan","id":"CAP-ARCHIVE-DELETE","status":"planned_critical"}
- CAP-PRIVACY-EXPORT: {"authority":"produce a named lower-sensitivity derivative","id":"CAP-PRIVACY-EXPORT","status":"planned"}
- CAP-HUMAN-CONFIRM: {"authority":"attach a scoped human confirmation receipt","id":"CAP-HUMAN-CONFIRM","status":"planned"}
- CAP-ADMIN-POLICY: {"authority":"modify registries/policies through a separately audited path","id":"CAP-ADMIN-POLICY","status":"planned_critical"}
- CAP-AGENT-ORIENT: {"authority":"read an anchor-bound four-ledger orientation projection within privacy and token budgets","id":"CAP-AGENT-ORIENT","status":"planned"}
- CAP-AGENT-QUERY: {"authority":"read bounded canonical or certified-derived facts and expand typed handles","id":"CAP-AGENT-QUERY","status":"planned"}
- CAP-BRANCH-SPECULATE: {"authority":"create and evaluate authority-free counterfactual branches over a pinned anchor","id":"CAP-BRANCH-SPECULATE","status":"planned"}
- CAP-PLAN-COMMIT: {"authority":"commit a sealed plan after current witness, policy, capability, idempotency, lease, and fence validation","id":"CAP-PLAN-COMMIT","status":"planned_critical"}
- CAP-HANDOFF-PUBLISH: {"authority":"publish an authority-free sealed handoff capsule for a named session/campaign","id":"CAP-HANDOFF-PUBLISH","status":"planned"}
- CAP-EPISODE-APPEND: {"authority":"append a validated immutable episode and surprise capsule to the operational evidence lineage","id":"CAP-EPISODE-APPEND","status":"planned"}
- CAP-DIAGNOSTIC-FORENSIC: {"authority":"read bounded raw diagnostic and evidence surfaces within explicit privacy scope","id":"CAP-DIAGNOSTIC-FORENSIC","status":"planned_sensitive"}
